  }

  listTags(query = '') {
    const key = String(query).trim().toLowerCase();
    return this.db.prepare(`
      SELECT tags.id, tags.name, COUNT(bookmark_tags.bookmark_id) AS usage_count
      FROM tags LEFT JOIN bookmark_tags ON bookmark_tags.tag_id = tags.id
