    if (options.throwOnFailure) throw error;
    return {
      title: fallbackTitle(url),
      description: '',
      siteName: url.hostname.replace(/^www\./, ''),
      siteIcon: `${url.origin}/favicon.ico`,
      previewImage: '',
      metadataStatus: 'unavailable'
