const state = {
  user: null,
  view: sessionStorage.getItem('stow:view') || 'active',
  query: sessionStorage.getItem('stow:query') || '',
  tag: sessionStorage.getItem('stow:tag') || '',
  items: [],
  tags: [],
  total: 0,
  counts: { active: 0, later: 0, aside: 0 },
  limit: 12,
  loading: false,
  highlightedId: null,
  menuId: null,
  expandedNotes: new Set(),
  draftContext: null
};

const icons = {
